const form=document.getElementById("login-form");form&&form.addEventListener("submit",()=>{const t=document.getElementById("login");t.setAttribute("aria-busy","true"),t.disabled=!0}),document.querySelectorAll("[data-copy-target]").forEach(t=>{t.addEventListener("click",()=>{const e=t.getAttribute("data-copy-target"),o=document.getElementById(e),n=document.getElementById(e+"-copy-status");o&&navigator.clipboard.writeText(o.value).then(()=>{n.textContent="Copied to clipboard",setTimeout(()=>n.textContent="",2e3)}).catch(()=>{n.textContent="Failed to copy text"})})});
document.querySelectorAll("form[data-confirm]").forEach(t=>{t.addEventListener("submit",e=>{window.confirm(t.getAttribute("data-confirm"))||e.preventDefault()})});document.querySelectorAll("input[data-filter]").forEach(t=>{const e=document.querySelectorAll("#"+t.getAttribute("data-filter")+" tbody tr");t.addEventListener("input",()=>{const o=t.value.trim().toLowerCase();e.forEach(t=>t.hidden=""!==o&&!t.textContent.toLowerCase().includes(o))})});